SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(8*10^9);Alarm(500);tt:=Cputime();
root:="work/deg10/continuation_20261030c/C99/";dat:=eval Read(root cat "Y29_model.m");raw:=eval Read(root cat "Y29_RR.m");assert raw[1] eq 3 and raw[8] eq 0 and raw[9] eq 110;
k:=GF(2);PP:=PolynomialRing(k);B<t>:=FunctionField(k);R<Z>:=PolynomialRing(B);
function Rat(v)return B!(PP!v[1])/B!(PP!v[2]);end function;
ff:=R![Rat(v):v in dat[1]];assert Degree(ff) eq 12 and IsIrreducible(ff);F<z>:=FunctionField(ff);assert Genus(F) eq 29;
function DF(v)return F![Rat(w):w in v];end function;
function RatAt(v,x)return Evaluate(PP!v[1],x)/Evaluate(PP!v[2],x);end function;
t9:=DF(dat[5]);sx:=DF(dat[6]);wx:=DF(dat[7]);j11:=DF(dat[8]);j9:=F!Rat(dat[2]);assert t9 eq F!B.1 and sx eq F.1;
assert &+[RatAt(dat[3][i],sx)*wx^(i-1):i in[1..#dat[3]]] eq 0;
assert &+[RatAt(dat[4][1][i],sx)*wx^(i-1):i in[1..#dat[4][1]]] eq j9;
assert &+[RatAt(dat[4][2][i],sx)*wx^(i-1):i in[1..#dat[4][2]]] eq j11;
Eco:=[Rat(v):v in dat[9]];E9:=EllipticCurve(Eco);P9:=E9![0,0];assert 9*P9 eq E9!0 and 3*P9 ne E9!0;
c:=t^2*(t-1);b:=c*(t^2-t+1);assert Eco eq [B|1-c,-b,-b,0,0] and c^2/(b-c) eq t and jInvariant(E9) eq Rat(dat[2]);
OF:=MaximalOrderFinite(F);OI:=MaximalOrderInfinite(F);zero:=DivisorGroup(F)!0;assert #Basis(zero:Reduction:=false,Simplification:="None") eq 1;
printf "C99_PEER_Y29_MODEL_READY absolute_degree12=true genus29=true exact_constantsF2=true Kubert9_and_X011_identities=true time=%o\n",Cputime(tt);
function ER(v)return [[Integers()!q:q in Coefficients(Numerator(v))],[Integers()!q:q in Coefficients(Denominator(v))]];end function;
function EF(v)return [ER(q):q in Eltseq(F!v)];end function;
function Key2(vals)
 K:=Parent(vals[1]);d:=LCM([Degree(MinimalPolynomial(v,k)):v in vals]);found:=false;
 for bits in [[1,0],[0,1],[1,1]] do gv:=&+[K!bits[i]*vals[i]:i in[1..2]];po:=MinimalPolynomial(gv,k);if Degree(po) eq d then chosen:=bits;found:=true;break;end if;end for;assert found;
 M:=Matrix(k,[Eltseq(gv^i,k):i in[0..d-1]]);assert Rank(M) eq d;co:=[Eltseq(Solution(M,Vector(k,Eltseq(v,k)))):v in vals];assert &and[&+[K!co[j][i+1]*gv^i:i in[0..d-1]] eq vals[j]:j in[1..2]];
 return [*d,chosen,[Integers()!q:q in Coefficients(po)],[[Integers()!q:q in row]:row in co]*];
end function;
function Prime(row)
 OO:=row[2] eq 1 select OF else OI;gens:=[DF(v):v in row[3]];I:=ideal<OO|gens>;assert IsIntegral(I) and IsPrime(I);Q:=Place(I);assert Ideal(Q) eq I and Degree(Q) eq row[1];g,h:=TwoGenerators(Q);assert ideal<OO|g,h> eq I;assert DF(EF(g)) eq g and DF(EF(h)) eq h;
 assert Valuation(j9,Q) eq 0 and Valuation(j11,Q) eq 0;key:=Key2([Evaluate(t9,Q),Evaluate(j11,Q)]);assert key[1] eq Degree(Q);
 return Q,key,[*row[1],row[2],[EF(g),EF(h)]*];
end function;
phases:=[];keys:=[* *];primeproof:=[* *];
for i in[2..5] do p,key,pk:=Prime(raw[i]);assert Degree(p) eq 10;Append(~phases,p);Append(~keys,key);Append(~primeproof,[*"source",i-1,pk,key*]);end for;
assert phases[1] eq phases[4] and #Seqset(phases) eq 3;
T:=zero;DT:=zero;terms:=[* *];npr:=4;
for i in[1..#raw[6]] do row:=raw[6][i];e,n,n2:=Explode(row[1..3]);p,kp,pp:=Prime(row[4]);p2,kp2,pp2:=Prime(row[5]);npr+:=2;assert 10*e eq n*Degree(p) and 10*e eq n2*Degree(p2) and n eq 1 and n2 eq 1;
 T+:=n*Divisor(p);DT+:=n2*Divisor(p2);Append(~terms,[*e,n,n2,kp,kp2*]);Append(~primeproof,[*"T",i,pp,kp*]);Append(~primeproof,[*"delta2T",i,pp2,kp2*]);end for;
assert [r[1]:r in terms] eq [1,1,2,2] and Degree(T) eq 60 and Degree(DT) eq 60;
D:=DT-T+Divisor(phases[1])-Divisor(phases[2])+5*Divisor(phases[3])-5*Divisor(phases[4]);assert Degree(D) eq 0;
Dsave:=zero;
for i in[1..#raw[7]] do row:=raw[7][i];p,key,pk:=Prime(row[1]);npr+:=1;Dsave+:=row[2]*Divisor(p);Append(~primeproof,[*"aggregate",row[2],pk,key*]);end for;
assert D eq Dsave;ps,es:=Support(D);pos:=&+[Integers()|Degree(ps[i])*Maximum(es[i],0):i in[1..#ps]];neg:=-&+[Integers()|Degree(ps[i])*Minimum(es[i],0):i in[1..#ps]];assert pos eq 110 and neg eq 110;
Write(root cat "peer_Y29_two_generators.m",Sprint(primeproof):Overwrite:=true);
printf "C99_PEER_Y29_DIVISOR_BOUND two_generators_roundtrips=true point_operator=alpha2A5 hecke_degree60=true signed_degree110=true checks=%o unique_support=%o time=%o\n",npr,#ps,Cputime(tt);
h0:=#Basis(D:Reduction:=false,Simplification:="None");assert h0 eq 0;
out:=[*keys,terms,h0,pos,npr*];Write(root cat "peer_native_Y29_RR.m",Sprint(out):Overwrite:=true);
printf "C99_PEER_Y29_NATIVE_COMPLETE h0=%o positive=%o negative=%o prime_checks=%o time=%o\n",h0,pos,neg,npr,Cputime(tt);quit;
